#include <type_traits>
#include <stdexcept>
#include <functional>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <list>
#include <map>
#include <unordered_map>

static const char* b2s(bool b) { return b ? "True" : "False"; }

class Buffer {
    std::vector<int> v_;
    int throwAfter_ = -1;

    void checkpoint() {
        if (throwAfter_ < 0) return;
        if (--throwAfter_ < 0) throw std::runtime_error("backend failure");
    }
public:
    void set_throw_after(int n) { throwAfter_ = n; }
    std::size_t size() const { return v_.size(); }

    // 基本保证：失败后对象仍有效，但状态可能已改变
    void add_basic(int x) {
        v_.push_back(x);     // 先改状态
        checkpoint();        // 再可能抛异常
    }
    // 强保证：先拷贝-修改，最后一步提交（swap 不抛）
    void add_strong(int x) {
        std::vector<int> tmp = v_;
        tmp.push_back(x);
        checkpoint();
        v_.swap(tmp);
    }
};

int main() {
    Buffer okb;
    okb.set_throw_after(-1);
    okb.add_basic(1);
    std::cout << "basic success size=" << okb.size() << "\n";

    Buffer b1;
    b1.set_throw_after(0);
    try { b1.add_basic(1); } catch (const std::exception&) {}
    std::cout << "basic after throw size=" << b1.size() << "\n";
    std::cout << "basic state changed (no rollback)=" << b2s(b1.size() == 1) << "\n";

    Buffer oks;
    oks.set_throw_after(-1);
    oks.add_strong(1);
    std::cout << "strong success size=" << oks.size() << "\n";

    Buffer b2;
    b2.set_throw_after(0);
    try { b2.add_strong(1); } catch (const std::exception&) {}
    std::cout << "strong after throw size=" << b2.size() << "\n";
    std::cout << "strong state unchanged=" << b2s(b2.size() == 0) << "\n";
}
